-- Name: current_org_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.current_org_id() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'app'
    AS $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.org_id', true), '')::uuid,
    auth.uid()
  )
$$;


--
-- Name: current_user_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.current_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'app'
    AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;


--
-- Name: leads_force_org_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.leads_force_org_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Auth context prioritaire (sécurité authed inchangée).
  -- Sans contexte (service_role), on respecte l'org_id explicite fourni.
  new.org_id := coalesce(app.current_org_id(), new.org_id);

  if new.org_id is null then
    raise exception 'missing org_id in auth context'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: leads_set_user_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.leads_set_user_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (to_jsonb(new) ? 'user_id') and new.user_id is null then
    new.user_id := new.created_by;
  end if;
  return new;
end;
$$;


