--
-- Name: ac_track_survey_reviews(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ac_track_survey_reviews() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_body   text;
  v_link   text;
  v_client text;
BEGIN
  IF (OLD.submitted_at IS NULL AND NEW.submitted_at IS NOT NULL)
     OR (OLD.rating IS NULL AND NEW.rating IS NOT NULL) THEN
    v_client := public.ac_client_name(NEW.client_id);
    v_body := 'Note ' || coalesce(NEW.rating::text, '?') || '/5'
           || coalesce(' · ' || v_client, '')
           || coalesce(' — ' || nullif(left(NEW.feedback, 140), ''), '');
    v_link := CASE
                WHEN NEW.job_id IS NOT NULL THEN '/jobs/' || NEW.job_id
                WHEN NEW.client_id IS NOT NULL THEN '/clients/' || NEW.client_id
              END;
    PERFORM public.ac_log_event(NEW.org_id, 'review_received', NULL, 'Avis client reçu', v_body, v_link, NEW.id, true, v_client);
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ac_track_survey_reviews failed: %', SQLERRM;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ai_enforce_org_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_enforce_org_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
begin
  -- Try to get org from current_org_id() if it exists
  begin
    v_org := public.current_org_id();
  exception when others then
    v_org := null;
  end;

  if v_org is not null then
    new.org_id := v_org;
  end if;

  return new;
end;
$$;


--
-- Name: ai_on_message_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_on_message_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.ai_conversations
  set
    last_message_preview = left(new.content, 200),
    last_message_role    = new.role,
    last_message_at      = new.created_at,
    message_count        = message_count + 1,
    total_input_tokens   = total_input_tokens + coalesce(new.input_tokens, 0),
    total_output_tokens  = total_output_tokens + coalesce(new.output_tokens, 0),
    total_estimated_cost = total_estimated_cost + coalesce(new.estimated_cost, 0)
  where id = new.conversation_id;

  return new;
end;
$$;


--
-- Name: ai_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: anonymize_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_client(p_client_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid;
  v_contact_id uuid;
  v_cols text;
  v_sql text;
begin
  select org_id, contact_id into v_org, v_contact_id
    from public.clients where id = p_client_id;
  if v_org is null then raise exception 'Client not found'; end if;
  -- N3.5 (audit 2026-07-31) : auth.uid() est NULL en service_role, donc
  -- has_org_admin_role(NULL, ...) renvoyait false et l'effacement echouait pour
  -- TOUT LE MONDE. On n'exige le role admin que d'un appelant authentifie ;
  -- le chemin serveur est borne par la verification d'org faite dans la route.
  if auth.uid() is not null and not public.has_org_admin_role(auth.uid(), v_org) then
    raise exception 'Only org admin/owner can anonymize clients';
  end if;

  -- Build SET clause dynamically from columns that actually exist
  select string_agg(
    case column_name
      when 'first_name' then 'first_name=''ANONYMIZED'''
      when 'last_name'  then 'last_name='''''
      else column_name || '=null'
    end, ', ')
    into v_cols
    from information_schema.columns
   where table_schema='public' and table_name='clients'
     and column_name in ('first_name','last_name','company','email','phone',
                         'address','address_line1','address_line2','street_number','street_name',
                         'city','province','postal_code','country',
                         'latitude','longitude','place_id','notes',
                         'sms_consent_at','email_consent_at');

  v_sql := format(
    'update public.clients set %s, deleted_at=coalesce(deleted_at, now()), updated_at=now() where id = %L',
    v_cols, p_client_id);
  execute v_sql;

  if v_contact_id is not null then
    update public.contacts
       set full_name='ANONYMIZED', email=null, phone=null,
           address_line1=null, address_line2=null,
           city=null, province=null, postal_code=null, country=null
     where id = v_contact_id;
  end if;

  insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_org, auth.uid(), 'anonymize', 'client', p_client_id, jsonb_build_object('method','dsr_erasure'));
end $$;


--
-- Name: anonymize_inactive_leads(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_inactive_leads(p_months integer DEFAULT 24) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cutoff timestamptz := now() - make_interval(months => p_months);
  v_count bigint := 0;
BEGIN
  WITH updated AS (
    UPDATE public.clients
       SET first_name = 'ANONYMIZED', last_name = '', title = null, company = null,
           email = null, phone = null, address = null, notes = null,
           tags = array[]::text[], updated_at = now()
     WHERE status = 'lead'
       AND updated_at < v_cutoff
       AND (first_name IS DISTINCT FROM 'ANONYMIZED' OR email IS NOT NULL OR phone IS NOT NULL)
       AND coalesce(lead_status, '') NOT IN ('closed_won', 'won')
    RETURNING id, org_id
  )
  INSERT INTO public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  SELECT org_id, null, 'anonymize', 'lead', id, jsonb_build_object('method','retention_24m','cutoff',v_cutoff)
    FROM updated;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END $$;


--
-- Name: anonymize_lead(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_lead(p_lead_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.clients
  SET first_name = 'ANONYMIZED', last_name = '', title = null, company = null,
      email = null, phone = null, address = null, notes = null,
      tags = array[]::text[], updated_at = now()
  WHERE id = p_lead_id;
END;
$$;


--
-- Name: anonymize_old_soft_deleted_clients(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_old_soft_deleted_clients(p_days integer DEFAULT 180) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_cutoff timestamptz := now() - make_interval(days => p_days);
  v_count bigint := 0;
  v_cols text;
  v_sql text;
begin
  select string_agg(
    case column_name
      when 'first_name' then 'first_name=''ANONYMIZED'''
      when 'last_name'  then 'last_name='''''
      else column_name || '=null'
    end, ', ')
    into v_cols
    from information_schema.columns
   where table_schema='public' and table_name='clients'
     and column_name in ('first_name','last_name','company','email','phone',
                         'address','address_line1','address_line2','street_number','street_name',
                         'city','province','postal_code','country',
                         'latitude','longitude','place_id','notes',
                         'sms_consent_at','email_consent_at');

  v_sql := format($X$
    with updated as (
      update public.clients set %s, updated_at=now()
       where deleted_at is not null and deleted_at < %L
         and first_name is distinct from 'ANONYMIZED'
      returning id, org_id)
    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    select org_id, null, 'anonymize', 'client', id,
           jsonb_build_object('method','retention_softdelete_180d','cutoff', %L::timestamptz) from updated
  $X$, v_cols, v_cutoff, v_cutoff);
  execute v_sql;
  get diagnostics v_count = row_count;
  return v_count;
end $_$;


