--
-- Name: bump_row_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_row_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- Un UPDATE qui ne change rien ne doit pas invalider la version d'autrui.
  if new is distinct from old then
    new.version := coalesce(old.version, 0) + 1;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION bump_row_version(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bump_row_version() IS 'N4.2 — garantit la progression de `version` et ignore les UPDATE sans changement. Ne remplace PAS la clause `where version = $n` cote applicatif, qui seule detecte le conflit.';


--
-- Name: business_days_between(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_days_between(p_start date, p_end date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::int
  FROM generate_series(p_start, p_end - 1, '1 day'::interval) d
  WHERE EXTRACT(isodow FROM d) < 6;
$$;


--
-- Name: cancel_hard_delete_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_hard_delete_member(p_member_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_org uuid; v_target uuid;
begin
  select org_id, user_id into v_org, v_target
    from public.team_members where id = p_member_id;
  if v_org is null then raise exception 'Team member not found'; end if;
  if auth.uid() is not null and not public.has_org_admin_role(auth.uid(), v_org) then
    raise exception 'Only org admin/owner can cancel deletion';
  end if;

  update public.team_members
     set deletion_scheduled_at = null,
         deletion_requested_by = null,
         updated_at = now()
   where id = p_member_id;

  -- Reactivate membership
  update public.memberships
     set status = 'active'
   where user_id = v_target and org_id = v_org;

  insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_org, auth.uid(), 'cancel_hard_delete', 'team_member', p_member_id,
    jsonb_build_object('target_user', v_target));
end $$;


--
-- Name: check_all_invariants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_all_invariants() RETURNS TABLE(check_name text, failures bigint, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  check_name := 'cross_tenant_references';
  select count(*), coalesce(string_agg(relation || '=' || violations, ', '), '')
    into failures, detail from public.check_cross_tenant_references();
  return next;

  check_name := 'invoice_totals_balance';
  select count(*), coalesce(string_agg(invoice_number, ', '), '')
    into failures, detail from public.check_invoice_totals_balance();
  return next;

  check_name := 'rls_coverage';
  select count(*), coalesce(string_agg(table_name, ', '), '')
    into failures, detail from public.check_rls_coverage();
  return next;

  check_name := 'invoice_numbering';
  select count(*), coalesce(string_agg(invoice_number, ', '), '')
    into failures, detail from public.check_invoice_numbering_invariant();
  return next;

  check_name := 'custom_field_orphans';
  select count(*), coalesce(string_agg(record_id::text, ', '), '')
    into failures, detail from public.check_custom_field_orphans();
  return next;

  -- NOUVEAU — un cron en echec ne se voit nulle part ailleurs.
  check_name := 'failing_cron_jobs';
  select count(*), coalesce(string_agg(jobname, ', '), '')
    into failures, detail from public.check_failing_cron_jobs();
  return next;

  -- NOUVEAU — regression du moindre privilege sur les fonctions trigger.
  check_name := 'exposed_trigger_functions';
  select count(*), coalesce(string_agg(function_name, ', '), '')
    into failures, detail from public.check_exposed_trigger_functions();
  return next;
end $$;


--
-- Name: FUNCTION check_all_invariants(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_all_invariants() IS 'N7.10 — Sonde unique pour le cron. Toute ligne avec failures > 0 doit alerter. Couvre : isolation multi-tenant, coherence des totaux, couverture RLS, numerotation des factures, orphelins de champs personnalises, crons en echec, et fonctions trigger exposees aux roles clients.';


--
-- Name: check_availability_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_availability_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.team_availability
    WHERE team_id = NEW.team_id
      AND weekday = NEW.weekday
      AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND deleted_at IS NULL
      AND NEW.start_minute < end_minute
      AND NEW.end_minute > start_minute
  ) THEN
    RAISE EXCEPTION 'Availability overlap detected for team % on weekday %', NEW.team_id, NEW.weekday;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_cross_tenant_references(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_cross_tenant_references() RETURNS TABLE(relation text, violations bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_count bigint;
begin
  for r in
    select c.conrelid::regclass::text as child,
           c.confrelid::regclass::text as parent,
           a.attname as fkcol
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
     where c.contype = 'f'
       and c.connamespace = 'public'::regnamespace
       and array_length(c.conkey, 1) = 1
       and c.conrelid <> c.confrelid
       and exists (select 1 from pg_attribute x
                    where x.attrelid = c.conrelid and x.attname = 'org_id' and not x.attisdropped)
       and exists (select 1 from pg_attribute x
                    where x.attrelid = c.confrelid and x.attname = 'org_id' and not x.attisdropped)
  loop
    execute format(
      'select count(*) from public.%I c join public.%I p on p.id = c.%I '
      'where c.org_id is distinct from p.org_id',
      r.child, r.parent, r.fkcol
    ) into v_count;

    if v_count > 0 then
      relation := format('%s.%s -> %s', r.child, r.fkcol, r.parent);
      violations := v_count;
      return next;
    end if;
  end loop;
end $$;


