-- Name: FUNCTION check_exposed_trigger_functions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_exposed_trigger_functions() IS 'N7.2 — Doit retourner 0 ligne. Une fonction trigger executable par un role client est une porte ouverte : Postgres accorde EXECUTE a PUBLIC par defaut, il faut le revoquer a chaque creation.';


--
-- Name: check_failing_cron_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_failing_cron_jobs() RETURNS TABLE(jobname text, failures_7d bigint, last_error text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select j.jobname::text,
         count(*) filter (where r.status = 'failed'),
         (array_agg(r.return_message order by r.end_time desc)
            filter (where r.status = 'failed'))[1]
    from cron.job j
    join cron.job_run_details r on r.jobid = j.jobid
   where r.start_time > now() - interval '7 days'
   group by j.jobname
  having count(*) filter (where r.status = 'failed') > 0;
$$;


