--
-- Name: check_password_strength(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_password_strength(p_password text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
    DECLARE v_score int := 0; v_issues text[] := '{}';
    BEGIN
      IF length(p_password) < 10 THEN v_issues := array_append(v_issues, 'Min 10 characters'); ELSE v_score := v_score + 1; END IF;
      IF p_password !~ '[A-Z]' THEN v_issues := array_append(v_issues, 'Need uppercase'); ELSE v_score := v_score + 1; END IF;
      IF p_password !~ '[a-z]' THEN v_issues := array_append(v_issues, 'Need lowercase'); ELSE v_score := v_score + 1; END IF;
      IF p_password !~ '[0-9]' THEN v_issues := array_append(v_issues, 'Need number'); ELSE v_score := v_score + 1; END IF;
      IF p_password !~ '[^a-zA-Z0-9]' THEN v_issues := array_append(v_issues, 'Need special char'); ELSE v_score := v_score + 1; END IF;
      IF length(p_password) >= 16 THEN v_score := v_score + 1; END IF;
      RETURN jsonb_build_object('strong', array_length(v_issues, 1) IS NULL OR array_length(v_issues, 1) = 0, 'score', v_score, 'max_score', 6, 'issues', to_jsonb(v_issues));
    END;
    $$;


--
-- Name: FUNCTION check_password_strength(p_password text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_password_strength(p_password text) IS 'Validate password strength';


--
-- Name: check_rate_limit(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit(p_action text, p_max_per_minute integer DEFAULT 60) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window timestamptz := date_trunc('minute', now());
  v_count int;
BEGIN
  INSERT INTO rate_limits (user_id, action, window_start, count)
  VALUES (auth.uid(), p_action, v_window, 1)
  ON CONFLICT (user_id, action, window_start)
  DO UPDATE SET count = rate_limits.count + 1
  RETURNING count INTO v_count;

  -- Cleanup old entries periodically
  IF random() < 0.01 THEN
    DELETE FROM rate_limits WHERE window_start < now() - INTERVAL '5 minutes';
  END IF;

  RETURN v_count <= p_max_per_minute;
END;
$$;


--
-- Name: check_rate_limit(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rate_limit(p_key text, p_max_tokens integer DEFAULT 60, p_refill_rate integer DEFAULT 1, p_cost integer DEFAULT 1) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tokens int;
BEGIN
  INSERT INTO rate_limit_buckets (key, tokens, max_tokens, refill_rate, last_refill)
  VALUES (p_key, p_max_tokens - p_cost, p_max_tokens, p_refill_rate, now())
  ON CONFLICT (key) DO UPDATE SET
    tokens = LEAST(rate_limit_buckets.max_tokens, rate_limit_buckets.tokens + FLOOR(EXTRACT(EPOCH FROM (now() - rate_limit_buckets.last_refill)) * rate_limit_buckets.refill_rate)::int) - p_cost,
    last_refill = now()
  RETURNING tokens INTO v_tokens;
  RETURN v_tokens >= 0;
END;
$$;


--
-- Name: FUNCTION check_rate_limit(p_key text, p_max_tokens integer, p_refill_rate integer, p_cost integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_rate_limit(p_key text, p_max_tokens integer, p_refill_rate integer, p_cost integer) IS 'Token bucket rate limiter — returns true if request allowed';


--
-- Name: check_rls_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rls_coverage() RETURNS TABLE(table_name text, rls_enabled boolean, rls_forced boolean, policy_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.relname::text, c.relrowsecurity, c.relforcerowsecurity,
         (select count(*) from pg_policy p where p.polrelid = c.oid)
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r'
     and (not c.relrowsecurity
          or not c.relforcerowsecurity
          or (not exists (select 1 from pg_policy p where p.polrelid = c.oid)
              -- deny-all assume : declare dans le commentaire de la table
              and coalesce(obj_description(c.oid, 'pg_class'), '') not like '%deny-all volontaire%'));
$$;


--
-- Name: FUNCTION check_rls_coverage(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_rls_coverage() IS 'N3.4 — Doit retourner 0 ligne. Table sans RLS activee, sans RLS forcee, ou avec RLS mais aucune policy. Une table peut declarer un deny-all assume en incluant « deny-all volontaire » dans son commentaire.';


