--
-- Name: check_team_schedule_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_team_schedule_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.availability_status = 'available' then
    if exists (
      select 1 from public.teams t
      where t.id = new.team_id
        and (t.deleted_at is not null or t.is_active = false)
    ) then
      raise exception 'TEAM_ARCHIVED: cannot assign to an archived team'
        using errcode = 'P0001';
    end if;

    if exists (
      select 1 from public.team_schedule_assignments a
      where a.user_id = new.user_id
        and a.work_date = new.work_date
        and a.id is distinct from new.id
        and a.availability_status = 'available'
        and a.start_time < new.end_time
        and a.end_time > new.start_time
    ) then
      raise exception 'SCHEDULE_OVERLAP: user is already assigned during these hours'
        using errcode = 'P0001';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: claim_next_invoice_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_next_invoice_number(p_org uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_num bigint;
begin
  insert into public.org_invoice_sequences (org_id, next_number)
    values (p_org, 1)
  on conflict (org_id) do nothing;

  update public.org_invoice_sequences
     set next_number = next_number + 1,
         updated_at  = now()
   where org_id = p_org
  returning next_number - 1 into v_num;

  return v_num;
end; $$;


