-- Name: FUNCTION claim_next_invoice_number(p_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_next_invoice_number(p_org uuid) IS 'Compteur alternatif (org_invoice_sequences), utilise par les tests de concurrence. Sur (UPDATE..RETURNING atomique) mais constitue une 2e source de verite. Ne pas utiliser en production : preferer invoice_next_number().';


--
-- Name: cleanup_expired_oauth_states(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_oauth_states() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_integration bigint := 0;
  v_email       bigint := 0;
begin
  delete from public.integration_oauth_states
   where expires_at < now();
  get diagnostics v_integration = row_count;

  -- Etait ABSENTE de la version precedente : c'est la table qui accumulait
  -- le plus de jetons perimes (9 lignes, jusqu'a 16 jours d'anciennete).
  delete from public.email_oauth_states
   where expires_at < now();
  get diagnostics v_email = row_count;

  return jsonb_build_object(
    'integration_oauth_states', v_integration,
    'email_oauth_states',       v_email,
    'purged_at',                now()
  );
end $$;


--
-- Name: FUNCTION cleanup_expired_oauth_states(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_expired_oauth_states() IS 'Purge les states OAuth expires des DEUX tables (integration + email). Planifiee toutes les heures : un state OAuth a une duree de vie de quelques minutes, le conserver au-dela n''a aucune utilite.';


--
-- Name: cleanup_expired_pipeline_deals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_pipeline_deals() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lost_count integer := 0;
  v_won_count  integer := 0;
BEGIN
  WITH deleted_lost AS (
    UPDATE public.pipeline_deals
    SET deleted_at = now(), updated_at = now()
    WHERE deleted_at IS NULL
      AND stage = 'closed_lost'
      AND lost_at IS NOT NULL
      AND lost_at <= now() - interval '15 days'
    RETURNING id
  )
  SELECT count(*) INTO v_lost_count FROM deleted_lost;

  WITH deleted_won AS (
    UPDATE public.pipeline_deals
    SET deleted_at = now(), updated_at = now()
    WHERE deleted_at IS NULL
      AND stage = 'closed_won'
      AND won_at IS NOT NULL
      AND won_at <= now() - interval '2 days'
    RETURNING id
  )
  SELECT count(*) INTO v_won_count FROM deleted_won;

  RETURN jsonb_build_object('lost_cleaned', v_lost_count, 'won_cleaned', v_won_count, 'cleaned_at', now());
END;
$$;


--
-- Name: cleanup_lost_pipeline_deals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_lost_pipeline_deals() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  update public.pipeline_deals
  set deleted_at = now(),
      updated_at = now()
  where deleted_at is null
    and lower(coalesce(stage, '')) = 'lost'
    and lost_at is not null
    and lost_at < now() - interval '15 days';

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: FUNCTION cleanup_lost_pipeline_deals(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_lost_pipeline_deals() IS 'Passe en soft-delete les opportunites perdues depuis plus de 15 jours. Remplace cleanup_lost_leads_10d(), supprimee : elle visait la table `leads` fusionnee dans `clients`, et ses colonnes de filtrage (stage, lost_at, converted_job_id) n''existent pas sur clients.';


