--
-- Name: ensure_payment_settings_row(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_payment_settings_row(p_org uuid) RETURNS public.payment_provider_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.payment_provider_settings;
begin
  if p_org is null then
    raise exception 'p_org is required';
  end if;

  insert into public.payment_provider_settings (org_id)
  values (p_org)
  on conflict (org_id) do nothing;

  select *
    into v_row
    from public.payment_provider_settings
   where org_id = p_org;

  return v_row;
end;
$$;


--
-- Name: execute_scheduled_member_deletions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_scheduled_member_deletions() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rec record;
  v_count bigint := 0;
begin
  for v_rec in
    select id, org_id, user_id from public.team_members
     where deletion_scheduled_at is not null
       and deletion_scheduled_at < now()
  loop
    -- Delete memberships (FK cascade from team_members if configured, else explicit)
    delete from public.memberships where user_id = v_rec.user_id and org_id = v_rec.org_id;
    -- Delete the team_member row
    delete from public.team_members where id = v_rec.id;

    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    values (v_rec.org_id, null, 'execute_hard_delete', 'team_member', v_rec.id,
      jsonb_build_object('target_user', v_rec.user_id, 'method', 'scheduled_30d'));

    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;


--
-- Name: export_client_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_client_data(p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_org uuid;
  v_result jsonb;
begin
  select org_id into v_org from public.clients where id = p_client_id;
  if v_org is null then
    raise exception 'Client not found';
  end if;

  -- Appel utilisateur : garde d'appartenance. Appel serveur (auth.uid() NULL) :
  -- l'autorisation est faite en amont dans server/routes/dsr.ts.
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), v_org) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'exported_at', now(),
    'client_id',   p_client_id,
    'client',      (select to_jsonb(c) from public.clients c where c.id = p_client_id),
    'contact',     (select to_jsonb(co) from public.contacts co where co.id = (select contact_id from public.clients where id = p_client_id)),
    'jobs',        (select coalesce(jsonb_agg(to_jsonb(j)), '[]'::jsonb) from public.jobs j where j.client_id = p_client_id),
    'invoices',    (select coalesce(jsonb_agg(to_jsonb(i)), '[]'::jsonb) from public.invoices i where i.client_id = p_client_id),
    'payments',    (select coalesce(jsonb_agg(to_jsonb(pm)), '[]'::jsonb) from public.payments pm where pm.client_id = p_client_id),
    'consents',    (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) from public.consents c where c.subject_type='client' and c.subject_id = p_client_id)
  ) into v_result;

  insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_org, auth.uid(), 'dsr_export', 'client', p_client_id, '{}'::jsonb);

  return v_result;
end $$;


--
-- Name: FUNCTION export_client_data(p_client_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.export_client_data(p_client_id uuid) IS 'Loi 25 art. 27 / RGPD art. 20 — export de portabilite d''un client. Garde d''appartenance sur appel utilisateur ; sur appel serveur (auth.uid() NULL) l''autorisation est faite dans server/routes/dsr.ts.';


--
-- Name: export_user_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_user_data(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_result jsonb;
  v_org    uuid;
begin
  -- Appel serveur (service_role) : auth.uid() est NULL et l'autorisation est
  -- faite en amont dans server/routes/dsr.ts. Appel utilisateur : la
  -- verification v_caller != p_user_id ci-dessous s'applique normalement.
  if v_caller is not null and v_caller <> p_user_id then
    if not exists (
      select 1 from public.memberships m1
      join public.memberships m2 on m1.org_id = m2.org_id
      where m1.user_id = v_caller
        and m2.user_id = p_user_id
        and public.has_org_admin_role(v_caller, m1.org_id)
    ) then
      raise exception 'Not authorized to export this user data' using errcode = '42501';
    end if;
  end if;

  select jsonb_build_object(
    'exported_at',       now(),
    'user_id',           p_user_id,
    'profile',           (select to_jsonb(p) from public.profiles p where p.id = p_user_id),
    'memberships',       (select coalesce(jsonb_agg(to_jsonb(m)), '[]'::jsonb) from public.memberships m where m.user_id = p_user_id),
    'consents',          (select coalesce(jsonb_agg(to_jsonb(c) order by c.created_at), '[]'::jsonb) from public.consents c where c.subject_type = 'user' and c.subject_id = p_user_id),
    'audit_events_as_actor', (select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at), '[]'::jsonb) from public.audit_events a where a.actor_id = p_user_id),
    'dsar_requests',     (select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at), '[]'::jsonb) from public.dsar_requests d where d.requested_by = p_user_id or (d.subject_type='user' and d.subject_id = p_user_id))
  ) into v_result;

  -- N3.1 — org_id etait code en dur a NULL : la ligne d'audit n'etait
  -- rattachee a aucun tenant, donc invisible dans toute consultation filtree.
  select m.org_id into v_org
    from public.memberships m
   where m.user_id = p_user_id
     and (v_caller is null or m.org_id in (
           select m2.org_id from public.memberships m2 where m2.user_id = v_caller))
   order by m.created_at
   limit 1;

  if v_org is null then
    select m.org_id into v_org
      from public.memberships m
     where m.user_id = p_user_id
     order by m.created_at
     limit 1;
  end if;

  -- Compte sans aucune org : on n'echoue pas. L'export est un droit legal
  -- (Loi 25 art. 27), il ne doit pas dependre de sa propre journalisation.
  if v_org is not null then
    insert into public.audit_events(org_id, actor_id, action, entity_type, entity_id, metadata)
    values (v_org, v_caller, 'dsr_export', 'user', p_user_id,
            jsonb_build_object('requested_by', v_caller));
  end if;

  return v_result;
end $$;


--
-- Name: FUNCTION export_user_data(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.export_user_data(p_user_id uuid) IS 'Loi 25 art. 27 / RGPD art. 20 — export de portabilite d''un utilisateur. Garde d''appartenance sur appel utilisateur ; sur appel serveur (auth.uid() NULL) l''autorisation est faite dans server/routes/dsr.ts.';


--
-- Name: field_compute_house_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_compute_house_score(p_house_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_visit_count       int;
  v_has_lead_status   boolean;
  v_last_activity     timestamptz;
BEGIN
  -- Count events in the last 30 days for this house
  SELECT COUNT(*)
  INTO v_visit_count
  FROM field_house_events
  WHERE house_id = p_house_id
    AND created_at >= now() - interval '30 days';

  -- Check whether the house currently has a lead-level status
  SELECT
    (current_status = 'lead'),
    last_activity_at
  INTO v_has_lead_status, v_last_activity
  FROM field_house_profiles
  WHERE id = p_house_id;

  -- Score logic
  IF v_visit_count >= 3 AND v_has_lead_status IS TRUE THEN
    RETURN 'hot';
  ELSIF v_visit_count >= 2
     OR (v_last_activity IS NOT NULL AND v_last_activity >= now() - interval '7 days')
  THEN
    RETURN 'warm';
  ELSE
    RETURN 'cold';
  END IF;
END;
$$;


--
-- Name: field_compute_next_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_compute_next_action(p_house_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status text;
BEGIN
  SELECT current_status
  INTO v_status
  FROM field_house_profiles
  WHERE id = p_house_id;

  RETURN CASE v_status
    WHEN 'no_answer'   THEN 'Revisit in 2 days'
    WHEN 'lead'        THEN 'Follow up'
    WHEN 'quote_sent'  THEN 'Check if quote opened'
    WHEN 'callback'    THEN 'Call back'
    WHEN 'sale'        THEN 'Send thank you'
    ELSE NULL
  END;
END;
$$;


--
-- Name: fill_property_id_from_job_or_client(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_property_id_from_job_or_client() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.property_id is null and new.job_id is not null then
    select j.property_id into new.property_id from public.jobs j where j.id = new.job_id;
  end if;
  if new.property_id is null and new.client_id is not null then
    new.property_id := public.resolve_primary_property(new.client_id);
  end if;
  return new;
end;
$$;


--
-- Name: find_duplicate_clients(uuid, text, text, text, text, real); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_duplicate_clients(p_org_id uuid, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_threshold real DEFAULT 0.3) RETURNS TABLE(client_id uuid, first_name text, last_name text, email text, phone text, company text, similarity_score real)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id, c.first_name, c.last_name, c.email, c.phone, c.company,
    GREATEST(
      CASE WHEN p_email IS NOT NULL AND c.email IS NOT NULL THEN
        CASE WHEN lower(c.email) = lower(p_email) THEN 1.0 ELSE similarity(c.email, p_email) END
      ELSE 0 END,
      CASE WHEN p_phone IS NOT NULL AND c.phone IS NOT NULL THEN
        similarity(regexp_replace(c.phone, '[^0-9]', '', 'g'), regexp_replace(p_phone, '[^0-9]', '', 'g'))
      ELSE 0 END,
      CASE WHEN p_first_name IS NOT NULL AND p_last_name IS NOT NULL THEN
        (similarity(c.first_name, p_first_name) + similarity(c.last_name, p_last_name)) / 2.0
      ELSE 0 END
    )::real AS similarity_score
  FROM clients c
  WHERE c.org_id = p_org_id AND c.deleted_at IS NULL
    AND (
      (p_email IS NOT NULL AND c.email IS NOT NULL AND (lower(c.email) = lower(p_email) OR similarity(c.email, p_email) > p_threshold))
      OR (p_phone IS NOT NULL AND c.phone IS NOT NULL AND similarity(regexp_replace(c.phone, '[^0-9]', '', 'g'), regexp_replace(p_phone, '[^0-9]', '', 'g')) > p_threshold)
      OR (p_first_name IS NOT NULL AND p_last_name IS NOT NULL AND (similarity(c.first_name, p_first_name) + similarity(c.last_name, p_last_name)) / 2.0 > p_threshold)
    )
  ORDER BY similarity_score DESC
  LIMIT 10;
END;
$$;


--
-- Name: finish_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_job_id uuid;
begin
  if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if not public.crm_is_org_admin(p_org_id, v_user) then raise exception 'Only owner/admin can finish job' using errcode='42501'; end if;

  update public.jobs
  set status = 'completed',
      completed_at = coalesce(completed_at, now()),
      updated_at = now()
  where id = p_job_id and org_id = p_org_id and deleted_at is null
  returning id into v_job_id;

  if v_job_id is null then
    return jsonb_build_object('ok', false, 'error', 'Job not found');
  end if;

  return jsonb_build_object('ok', true, 'job_id', v_job_id);
end;
$$;


--
-- Name: finish_job_and_prepare_invoice(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_job_and_prepare_invoice(p_org_id uuid, p_job_id uuid) RETURNS TABLE(ok boolean, invoice_id uuid, already_exists boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_org_id uuid := coalesce(p_org_id, public.current_org_id());
  v_payload jsonb := '{}'::jsonb;
  v_invoice_id uuid;
  v_already_exists boolean := false;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if v_org_id is null or p_job_id is null then
    raise exception 'p_org_id and p_job_id are required' using errcode = '22023';
  end if;

  -- Allow every CRM member in org to finish jobs.
  if not public.has_org_membership(v_uid, v_org_id) then
    raise exception 'Forbidden for this organization.' using errcode = '42501';
  end if;

  perform 1
  from public.jobs j
  where j.id = p_job_id
    and j.org_id = v_org_id
    and j.deleted_at is null
  for update;

  if not found then
    raise exception 'Job not found.' using errcode = 'P0002';
  end if;

  update public.jobs
  set status = 'completed',
      completed_at = coalesce(completed_at, now()),
      updated_at = now()
  where id = p_job_id
    and org_id = v_org_id
    and deleted_at is null;

  if to_regprocedure('public.create_invoice_from_job(uuid,uuid,boolean)') is not null then
    execute 'select public.create_invoice_from_job($1,$2,$3)'
      into v_payload
      using v_org_id, p_job_id, false;
  elsif to_regprocedure('public.create_invoice_from_job(uuid,uuid)') is not null then
    execute 'select public.create_invoice_from_job($1,$2)'
      into v_payload
      using v_org_id, p_job_id;
  end if;

  begin
    v_invoice_id := nullif(v_payload->>'invoice_id', '')::uuid;
  exception when others then
    v_invoice_id := null;
  end;

  if v_invoice_id is null then
    select i.id
      into v_invoice_id
    from public.invoices i
    where i.org_id = v_org_id
      and i.job_id = p_job_id
      and i.deleted_at is null
    order by i.created_at desc
    limit 1;

    v_already_exists := v_invoice_id is not null;
  else
    v_already_exists := coalesce((v_payload->>'already_exists')::boolean, false);
  end if;

  if v_invoice_id is null then
    raise exception 'Unable to prepare invoice from job.' using errcode = 'P0001';
  end if;

  return query
  select true, v_invoice_id, v_already_exists;
end;
$_$;


--
-- Name: fn_field_daily_stats_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_field_daily_stats_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d date := (NEW.created_at AT TIME ZONE 'UTC')::date;
BEGIN
  INSERT INTO public.field_daily_stats (org_id, user_id, date,
    knocks, no_answers, leads, quotes_sent, sales, callbacks)
  VALUES (NEW.org_id, NEW.user_id, d,
    CASE WHEN NEW.event_type = 'knock'      THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'no_answer'  THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'lead'       THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'quote_sent' THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'sale'       THEN 1 ELSE 0 END,
    CASE WHEN NEW.event_type = 'callback'   THEN 1 ELSE 0 END)
  ON CONFLICT (org_id, user_id, date) DO UPDATE SET
    knocks      = public.field_daily_stats.knocks      + EXCLUDED.knocks,
    no_answers  = public.field_daily_stats.no_answers  + EXCLUDED.no_answers,
    leads       = public.field_daily_stats.leads       + EXCLUDED.leads,
    quotes_sent = public.field_daily_stats.quotes_sent + EXCLUDED.quotes_sent,
    sales       = public.field_daily_stats.sales       + EXCLUDED.sales,
    callbacks   = public.field_daily_stats.callbacks   + EXCLUDED.callbacks;

  -- Recompute conversion rate (sales / knocks).
  UPDATE public.field_daily_stats
     SET conversion_rate = CASE WHEN knocks > 0
            THEN ROUND((sales::numeric / knocks::numeric) * 100, 2) ELSE 0 END
   WHERE org_id = NEW.org_id AND user_id = NEW.user_id AND date = d;

  RETURN NEW;
END;
$$;


--
-- Name: fn_push_on_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_push_on_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'net'
    AS $$
DECLARE
  msgs jsonb;
BEGIN
  -- Build one Expo push message per target device (only Expo tokens).
  SELECT COALESCE(
    jsonb_agg(jsonb_build_object(
      'to', pt.token,
      'title', NEW.title,
      'body', COALESCE(NEW.body, ''),
      'sound', 'default'
    )), '[]'::jsonb)
  INTO msgs
  FROM public.push_tokens pt
  WHERE pt.org_id = NEW.org_id
    AND (NEW.user_id IS NULL OR pt.user_id = NEW.user_id)
    AND pt.token LIKE 'ExponentPushToken%';

  IF msgs <> '[]'::jsonb THEN
    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := msgs
    );
  END IF;
  RETURN NEW;
END;
$$;


