-- Name: generate_workflow_public_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_workflow_public_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  next_num integer;
BEGIN
  SELECT COALESCE(MAX(
    CAST(REPLACE(public_id, 'WF-', '') AS integer)
  ), 1000) + 1
  INTO next_num
  FROM public.workflows
  WHERE org_id = NEW.org_id
    AND public_id LIKE 'WF-%';
  NEW.public_id := 'WF-' || next_num;
  RETURN NEW;
END;
$$;


--
-- Name: get_audit_log(uuid, text, uuid, text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_log(p_org_id uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, actor_id uuid, action text, entity_type text, entity_id uuid, event_type text, old_values jsonb, new_values jsonb, metadata jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT ae.id, ae.actor_id, ae.action, ae.entity_type, ae.entity_id,
         ae.event_type, ae.old_values, ae.new_values, ae.metadata, ae.created_at
  FROM audit_events ae
  WHERE ae.org_id = p_org_id
    AND (p_entity_type IS NULL OR ae.entity_type = p_entity_type)
    AND (p_entity_id IS NULL OR ae.entity_id = p_entity_id)
    AND (p_action IS NULL OR ae.action = p_action)
    AND (p_from IS NULL OR ae.created_at >= p_from)
    AND (p_to IS NULL OR ae.created_at <= p_to)
  ORDER BY ae.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: get_available_slots(uuid, uuid, date, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_slots(p_org_id uuid, p_team_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT CURRENT_DATE, p_days integer DEFAULT 14, p_slot_minutes integer DEFAULT 30, p_timezone text DEFAULT 'America/Toronto'::text) RETURNS TABLE(slot_start timestamp with time zone, slot_end timestamp with time zone, team_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_days int := greatest(1, least(coalesce(p_days, 14), 31));
  v_slot int := greatest(15, least(coalesce(p_slot_minutes, 30), 180));
  v_tz text := coalesce(nullif(trim(p_timezone), ''), 'America/Toronto');
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null then
    raise exception 'p_org_id is required' using errcode = '22023';
  end if;

  if not public.has_org_membership(v_uid, p_org_id) then
    raise exception 'Not a member of this org' using errcode = '42501';
  end if;

  return query
  with days as (
    select (p_start_date + g.d)::date as day_local
    from generate_series(0, v_days - 1) as g(d)
  ),
  windows as (
    select
      d.day_local,
      a.team_id,
      a.start_minute,
      a.end_minute,
      coalesce(nullif(trim(a.timezone), ''), v_tz) as tz
    from days d
    join public.team_availability a
      on a.org_id = p_org_id
     and a.deleted_at is null
     and a.weekday = extract(dow from d.day_local)::int
     and (p_team_id is null or a.team_id = p_team_id)
  ),
  slots as (
    select
      ((w.day_local::timestamp + make_interval(mins => m.minute_val)) at time zone w.tz) as s_start,
      ((w.day_local::timestamp + make_interval(mins => m.minute_val + v_slot)) at time zone w.tz) as s_end,
      w.team_id as t_id
    from windows w
    cross join lateral generate_series(w.start_minute, w.end_minute - v_slot, v_slot) as m(minute_val)
  )
  select s.s_start, s.s_end, s.t_id
  from slots s
  where not exists (
    select 1
    from public.schedule_events se
    left join public.jobs j on j.id = se.job_id
    where se.org_id = p_org_id
      and se.deleted_at is null
      and coalesce(se.start_at, se.start_time) < s.s_end
      and coalesce(se.end_at, se.end_time) > s.s_start
      and (
        p_team_id is null
        or coalesce(se.team_id, j.team_id) = p_team_id
      )
  )
  order by s.s_start asc;
end;
$$;


--
-- Name: get_entity_activity(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_entity_activity(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(event_id uuid, action text, event_type text, actor_id uuid, metadata jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_org_membership(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  SELECT ae.id, ae.action, ae.event_type, ae.actor_id, ae.metadata, ae.created_at
  FROM audit_events ae
  WHERE ae.org_id = p_org_id
    AND ae.entity_type = p_entity_type
    AND ae.entity_id = p_entity_id
  ORDER BY ae.created_at DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: get_invoice_next_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invoice_next_number(p_org uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_last integer;
begin
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), p_org) then
    raise exception 'Not a member of this organization.' using errcode = '42501';
  end if;
  select last_value into v_last from public.invoice_sequences where org_id = p_org;
  return coalesce(v_last, 0) + 1;
end;
$$;


--
-- Name: get_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job(p_org_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_job jsonb;
begin
  if v_user is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if not public.crm_is_org_member(p_org_id, v_user) then raise exception 'Forbidden' using errcode='42501'; end if;

  select to_jsonb(j.*) into v_job
  from public.jobs j
  where j.id = p_job_id and j.org_id = p_org_id and j.deleted_at is null;

  if v_job is null then
    return jsonb_build_object('ok', false, 'error', 'Job not found');
  end if;

  return jsonb_build_object('ok', true, 'job', v_job);
end;
$$;


--
-- Name: get_job_kpis(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_job_kpis(p_org_id uuid, p_status text DEFAULT NULL::text, p_job_type text DEFAULT NULL::text, p_q text DEFAULT NULL::text) RETURNS TABLE(ending_within_30 integer, late integer, requires_invoicing integer, action_required integer, unscheduled integer, recent_visits integer, recent_visits_prev integer, visits_scheduled integer, visits_scheduled_prev integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  return query
  with base as (
    select *
    from public.jobs
    where org_id = p_org_id
      and (p_status is null or status = p_status)
      and (p_job_type is null or job_type = p_job_type)
      and (
        p_q is null
        or job_number ilike '%' || p_q || '%'
        or title ilike '%' || p_q || '%'
        or property_address ilike '%' || p_q || '%'
        or coalesce(client_name, '') ilike '%' || p_q || '%'
      )
  )
  select
    count(*) filter (where scheduled_at is not null and scheduled_at >= now() and scheduled_at < now() + interval '30 days') as ending_within_30,
    count(*) filter (where status = 'Late') as late,
    count(*) filter (where status = 'Requires Invoicing') as requires_invoicing,
    count(*) filter (where status = 'Action Required') as action_required,
    count(*) filter (where status = 'Unscheduled' or scheduled_at is null) as unscheduled,
    count(*) filter (where scheduled_at >= now() - interval '30 days' and scheduled_at < now()) as recent_visits,
    count(*) filter (where scheduled_at >= now() - interval '60 days' and scheduled_at < now() - interval '30 days') as recent_visits_prev,
    count(*) filter (where scheduled_at >= now() and scheduled_at < now() + interval '30 days') as visits_scheduled,
    count(*) filter (where scheduled_at >= now() + interval '30 days' and scheduled_at < now() + interval '60 days') as visits_scheduled_prev
  from base;
end;
$$;


