--
-- Name: has_org_role(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_org_role(p_user uuid, p_org uuid, p_roles text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_exists boolean := false;
begin
  if p_user is null or p_org is null then
    return false;
  end if;

  if to_regclass('public.memberships') is not null then
    select exists (
      select 1
      from public.memberships m
      where m.user_id = p_user
        and m.org_id = p_org
        and m.role = any(p_roles)
    ) into v_exists;
    if v_exists then return true; end if;
  end if;

  if to_regclass('public.org_memberships') is not null then
    execute $q$
      select exists(
        select 1 from public.org_memberships m
        where m.user_id = $1 and m.org_id = $2 and m.role = any($3)
      )
    $q$ into v_exists using p_user, p_org, p_roles;
    if v_exists then return true; end if;
  end if;

  if to_regclass('public.org_members') is not null then
    execute $q$
      select exists(
        select 1 from public.org_members m
        where m.user_id = $1 and m.org_id = $2 and m.role = any($3)
      )
    $q$ into v_exists using p_user, p_org, p_roles;
    if v_exists then return true; end if;
  end if;

  return false;
end;
$_$;


--
-- Name: haversine_distance(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.haversine_distance(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  R constant double precision := 6371000;
  dlat double precision;
  dlng double precision;
  a double precision;
BEGIN
  dlat := radians(lat2 - lat1);
  dlng := radians(lng2 - lng1);
  a := sin(dlat/2)^2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2)^2;
  RETURN R * 2 * atan2(sqrt(a), sqrt(1 - a));
END;
$$;


