--
-- Name: invalidate_all_sessions(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_all_sessions(p_user_id uuid, p_reason text DEFAULT 'manual'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE v_count int;
    BEGIN
      UPDATE active_sessions SET is_valid = false, invalidated_reason = p_reason WHERE user_id = p_user_id AND is_valid = true;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      INSERT INTO security_events (user_id, event_type, severity, source, details)
      VALUES (p_user_id, 'sessions_invalidated', 'high', 'auth', jsonb_build_object('reason', p_reason, 'count', v_count));
      RETURN v_count;
    END;
    $$;


--
-- Name: FUNCTION invalidate_all_sessions(p_user_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invalidate_all_sessions(p_user_id uuid, p_reason text) IS 'Force-invalidate all sessions for a user';


