--
-- Name: invoice_items_set_line_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_items_set_line_total() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.qty := greatest(coalesce(new.qty, 1), 0);
  new.unit_price_cents := greatest(coalesce(new.unit_price_cents, 0), 0);
  new.line_total_cents := greatest(round(new.qty * new.unit_price_cents)::integer, 0);
  return new;
end;
$$;


--
-- Name: invoice_items_sync_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_items_sync_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
begin
  select org_id
    into v_org
  from public.invoices
  where id = new.invoice_id
    and deleted_at is null
  limit 1;

  if v_org is null then
    raise exception 'Invoice not found for item';
  end if;

  new.org_id := v_org;
  return new;
end;
$$;


--
-- Name: invoice_next_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_next_number(p_org uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_next bigint;
begin
  -- Garde cross-org conservée du fix 20260620.
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), p_org) then
    raise exception 'Not allowed for this organization';
  end if;

  -- Sérialise l'attribution par org (deux créations simultanées ne peuvent
  -- pas recevoir le même « plus petit numéro libre »).
  perform pg_advisory_xact_lock(hashtextextended(p_org::text || ':invoice', 0));

  v_next := public.org_smallest_free_number(p_org, 'invoice');

  insert into public.invoice_sequences (org_id, last_value)
  values (p_org, v_next)
  on conflict (org_id) do update
    set last_value = greatest(public.invoice_sequences.last_value, excluded.last_value),
        updated_at = now();

  return v_next::text;
end;
$$;


--
-- Name: FUNCTION invoice_next_number(p_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.invoice_next_number(p_org uuid) IS 'N3.7 — CHEMIN OFFICIEL de numerotation des factures. Serialise par org via pg_advisory_xact_lock. Source de verite : invoice_sequences. Toute nouvelle numerotation DOIT passer par ici.';


--
-- Name: invoices_apply_status_logic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoices_apply_status_logic() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.subtotal_cents := greatest(coalesce(new.subtotal_cents, 0), 0);
  new.tax_cents := greatest(coalesce(new.tax_cents, 0), 0);
  new.total_cents := greatest(new.subtotal_cents + new.tax_cents, 0);
  new.paid_cents := greatest(coalesce(new.paid_cents, 0), 0);

  if new.paid_cents > new.total_cents then
    new.paid_cents := new.total_cents;
  end if;

  new.balance_cents := greatest(new.total_cents - new.paid_cents, 0);

  if coalesce(new.status, '') = 'void' then
    if new.paid_cents = 0 then
      new.paid_at := null;
    end if;
    return new;
  end if;

  if new.issued_at is null then
    new.status := 'draft';
    if new.paid_cents = 0 then
      new.paid_at := null;
    end if;
    return new;
  end if;

  if new.balance_cents = 0 then
    new.status := 'paid';
    if new.paid_at is null then
      new.paid_at := now();
    end if;
    return new;
  end if;

  if new.paid_cents > 0 then
    new.status := 'partial';
  else
    new.status := 'sent';
  end if;

  if new.balance_cents > 0 then
    new.paid_at := null;
  end if;

  return new;
end;
$$;


