--
-- Name: jobs_sync_future_events_team(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_sync_future_events_team() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  if old.team_id is not distinct from new.team_id then
    return new;
  end if;

  update public.schedule_events se
  set team_id = new.team_id,
      updated_at = now()
  where se.job_id = new.id
    and se.org_id = new.org_id
    and se.deleted_at is null
    and se.start_at >= now();

  return new;
end;
$$;


--
-- Name: jobs_sync_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_sync_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'app'
    AS $$
begin
  if new.total_cents is null and new.total_amount is not null then
    new.total_cents := round(new.total_amount * 100)::integer;
  end if;
  if new.total_amount is null and new.total_cents is not null then
    new.total_amount := round(new.total_cents::numeric / 100, 2);
  end if;
  new.total_cents := coalesce(new.total_cents, 0);
  new.total_amount := coalesce(new.total_amount, round(new.total_cents::numeric / 100, 2));
  return new;
end;
$$;


--
-- Name: leads_before_insert_enforce_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_before_insert_enforce_scope() RETURNS trigger
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid;
  v_org uuid;
begin
  v_user := auth.uid();

  -- SQL Editor / service role: exige valeurs explicites
  if v_user is null then
    if new.org_id is null then
      raise exception 'org_id is required when no auth context' using errcode = '23502';
    end if;
    if new.created_by is null then
      raise exception 'created_by is required when no auth context' using errcode = '23502';
    end if;
    return new;
  end if;

  v_org := public.current_org_id();
  if v_org is null then
    v_org := v_user;
  end if;

  new.org_id := v_org;
  new.created_by := v_user;

  return new;
end;
$$;


