--
-- Name: lume_storage_object_org(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lume_storage_object_org(object_name text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  segments text[] := string_to_array(object_name, '/');
  candidate text;
begin
  foreach candidate in array segments[1:2] loop
    begin
      return candidate::uuid;
    exception when invalid_text_representation then
      null;
    end;
  end loop;
  return null;
end $$;


