CREATE FUNCTION public.mark_job_geocode_pending() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if nullif(trim(coalesce(new.property_address, '')), '') is not null then
      new.geocode_status := coalesce(new.geocode_status, 'pending');
    end if;
    return new;
  end if;

  if coalesce(trim(old.property_address), '') is distinct from coalesce(trim(new.property_address), '') then
    new.geocode_status := 'pending';
    new.geocoded_at := null;
    new.latitude := null;
    new.longitude := null;
  end if;

  return new;
end;
$$;


--
-- Name: next_recurrence_at(timestamp with time zone, text, integer, text, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_recurrence_at(p_from timestamp with time zone, p_frequency text, p_interval integer DEFAULT 7, p_timezone text DEFAULT 'America/Toronto'::text, p_local_time time without time zone DEFAULT NULL::time without time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_local_ts   timestamp;
  v_local_date date;
  v_time       time;
  v_next_date  date;
begin
  -- 1. Passer en heure locale du tenant.
  v_local_ts   := p_from at time zone p_timezone;
  v_local_date := v_local_ts::date;
  v_time       := coalesce(p_local_time, v_local_ts::time);

  -- 2. Avancer la DATE (jamais l'instant) selon la frequence.
  v_next_date := case p_frequency
    when 'daily'    then v_local_date + 1
    when 'weekly'   then v_local_date + 7
    when 'biweekly' then v_local_date + 14
    when 'monthly'  then (v_local_date + interval '1 month')::date
    when 'custom'   then v_local_date + greatest(coalesce(p_interval, 7), 1)
    else                 v_local_date + 7
  end;

  -- 3. Recomposer l'instant : date locale + heure locale, interprete dans le
  --    fuseau du tenant. Postgres applique le bon offset DST automatiquement.
  return (v_next_date + v_time) at time zone p_timezone;
end $$;


--
-- Name: FUNCTION next_recurrence_at(p_from timestamp with time zone, p_frequency text, p_interval integer, p_timezone text, p_local_time time without time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.next_recurrence_at(p_from timestamp with time zone, p_frequency text, p_interval integer, p_timezone text, p_local_time time without time zone) IS 'N2.7 — Calcule la prochaine occurrence en heure LOCALE + fuseau. Remplace l''arithmetique UTC (setDate(+7)) qui decalait les visites d''une heure a chaque changement d''heure. Testee sur la transition du 1er nov 2026.';


--
-- Name: normalize_lead_stage_value(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_lead_stage_value(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v text;
begin
  v := lower(trim(coalesce(p_value, '')));
  if v in ('qualified','new','nouveau') then
    return 'qualified';
  elsif v in ('quote_sent','quote sent','quote-sent','proposal','quoted') then
    return 'quote_sent';
  elsif v in ('contacted','contact','in_contact','in-contact') then
    return 'contacted';
  elsif v in ('closed','won','converted','complete','completed') then
    return 'closed';
  elsif v in ('lost','dead','cancelled','canceled') then
    return 'lost';
  else
    return 'qualified';
  end if;
end;
$$;


--
-- Name: normalize_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_phone(p_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_digits text;
begin
  if p_phone is null then return null; end if;
  v_digits := regexp_replace(p_phone, '\D', '', 'g');
  if length(v_digits) = 10 then return '+1' || v_digits; end if;
  if length(v_digits) = 11 and substr(v_digits, 1, 1) = '1' then return '+' || v_digits; end if;
  if length(v_digits) > 0 then return '+' || v_digits; end if;
  return null;
end; $$;


--
-- Name: normalize_phone_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_phone_digits(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g')
$$;


