--
-- Name: org_smallest_free_number(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_smallest_free_number(p_org uuid, p_entity text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_tbl text;
  v_col text;
  v_result bigint;
begin
  -- Garde cross-org (même règle que le fix 20260620 sur invoice_next_number) :
  -- un utilisateur authentifié ne peut lire que les numéros de son org.
  if auth.uid() is not null and not public.has_org_membership(auth.uid(), p_org) then
    raise exception 'Not allowed for this organization';
  end if;

  if p_entity = 'job' then v_tbl := 'jobs'; v_col := 'job_number';
  elsif p_entity = 'quote' then v_tbl := 'quotes'; v_col := 'quote_number';
  elsif p_entity = 'invoice' then v_tbl := 'invoices'; v_col := 'invoice_number';
  elsif p_entity = 'client' then v_tbl := 'clients'; v_col := 'client_number';
  else raise exception 'Unknown entity "%"', p_entity using errcode = '22023';
  end if;

  execute format(
    'with nums as (
       select distinct nullif(regexp_replace(%1$I, ''\D'', '''', ''g''), '''')::bigint as n
       from public.%2$I
       where org_id = $1 and %1$I ~ ''\d''
     )
     select min(s.s)
     from generate_series(1, coalesce((select count(*) from nums), 0) + 1) as s(s)
     where not exists (select 1 from nums where nums.n = s.s)',
    v_col, v_tbl)
  into v_result
  using p_org;

  return coalesce(v_result, 1);
end;
$_$;


--
-- Name: payments_recalculate_invoice_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_recalculate_invoice_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.recalculate_invoice_from_payments(new.invoice_id);
    return new;
  elsif tg_op = 'UPDATE' then
    if old.invoice_id is distinct from new.invoice_id then
      perform public.recalculate_invoice_from_payments(old.invoice_id);
      perform public.recalculate_invoice_from_payments(new.invoice_id);
    else
      perform public.recalculate_invoice_from_payments(new.invoice_id);
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    perform public.recalculate_invoice_from_payments(old.invoice_id);
    return old;
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: payments_sync_dates_and_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_sync_dates_and_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.payment_date := coalesce(new.payment_date, new.paid_at, new.created_at, now());
  new.paid_at := new.payment_date;
  new.updated_at := now();
  return new;
end;
$$;


