--
-- Name: pipeline_deals_cascade_client_soft_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pipeline_deals_cascade_client_soft_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- When a client gets soft-deleted, soft-delete their pipeline deals too
  if old.deleted_at is null and new.deleted_at is not null then
    update public.pipeline_deals
    set deleted_at = now(), updated_at = now()
    where client_id = new.id
      and deleted_at is null;
  end if;
  return new;
end;
$$;


--
-- Name: pipeline_deals_emit_job_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pipeline_deals_emit_job_intent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_stage_slug text;
  v_active_job_exists boolean;
begin
  if new.lead_id is null then
    return new;
  end if;

  v_stage_slug := lower(replace(coalesce(new.stage, ''), ' ', '_'));

  if v_stage_slug <> 'qualified' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if lower(replace(coalesce(old.stage, ''), ' ', '_')) = 'qualified' then
      return new;
    end if;
  end if;

  select exists (
    select 1
    from public.jobs j
    where j.lead_id = new.lead_id
      and j.deleted_at is null
      and lower(coalesce(j.status, 'unscheduled')) not in ('done', 'canceled', 'cancelled', 'completed')
  ) into v_active_job_exists;

  if v_active_job_exists then
    return new;
  end if;

  insert into public.job_intents (org_id, lead_id, deal_id, triggered_stage, status, created_by)
  values (new.org_id, new.lead_id, new.id, v_stage_slug, 'pending', auth.uid())
  on conflict (lead_id) where status = 'pending' and deleted_at is null
  do update set
    deal_id = excluded.deal_id,
    triggered_stage = excluded.triggered_stage,
    created_at = now(),
    created_by = excluded.created_by,
    org_id = excluded.org_id;

  return new;
end;
$$;


--
-- Name: pipeline_deals_sync_value_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pipeline_deals_sync_value_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'app'
    AS $$
begin
  -- If app sends only value
  if new.value is not null and (new.value_cents is null or tg_op = 'INSERT') then
    new.value_cents := round(new.value * 100)::integer;
  end if;

  -- If app sends only value_cents
  if new.value_cents is not null and new.value is null then
    new.value := round((new.value_cents::numeric / 100.0), 2);
  end if;

  -- Final safety
  new.value := coalesce(new.value, 0);
  new.value_cents := coalesce(new.value_cents, round(new.value * 100)::integer);

  return new;
end;
$$;


--
-- Name: pipeline_deals_sync_values(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pipeline_deals_sync_values() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if to_jsonb(new) ? 'value' and to_jsonb(new) ? 'value_cents' then
    if new.value is null and new.value_cents is not null then
      new.value := new.value_cents::numeric / 100;
    elsif new.value_cents is null and new.value is not null then
      new.value_cents := round(new.value * 100)::integer;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: prevent_paid_invoice_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_paid_invoice_edit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if OLD.status = 'paid' and NEW.status = 'paid' then
    if coalesce(OLD.total_cents, 0) is distinct from coalesce(NEW.total_cents, 0) then
      raise exception 'Cannot modify total on a paid invoice (use void + new invoice instead)'
        using errcode = 'check_violation';
    end if;
    if coalesce(OLD.balance_cents, 0) is distinct from coalesce(NEW.balance_cents, 0) and NEW.balance_cents > 0 then
      raise exception 'Cannot re-open a paid invoice'
        using errcode = 'check_violation';
    end if;
  end if;
  return NEW;
end; $$;


--
-- Name: provision_sms_channel(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_sms_channel(p_org_id uuid, p_phone_number text, p_provider text DEFAULT 'twilio'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_channel_id uuid;
BEGIN
  -- Deactivate any existing SMS channels for this org
  UPDATE public.communication_channels
  SET is_default = false, status = 'inactive'
  WHERE org_id = p_org_id AND channel_type = 'sms' AND is_default = true;

  -- Insert new channel
  INSERT INTO public.communication_channels (
    org_id, channel_type, provider, phone_number, is_default, status, metadata
  ) VALUES (
    p_org_id, 'sms', p_provider, p_phone_number, true, 'active', p_metadata
  )
  RETURNING id INTO v_channel_id;

  -- Update settings
  UPDATE public.communication_settings
  SET sms_enabled = true, default_sms_channel_id = v_channel_id, sms_two_way_enabled = true
  WHERE org_id = p_org_id;

  RETURN v_channel_id;
END;
$$;


--
-- Name: purge_expired_portal_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_portal_tokens() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_count bigint := 0;
begin
  -- Table doit exister (créée par migration portal_tokens antérieure)
  if to_regclass('public.portal_tokens') is null then
    return 0;
  end if;

  delete from public.portal_tokens
   where (revoked_at is not null and revoked_at < now() - interval '30 days')
      or (expires_at is not null and expires_at < now() - interval '180 days');
  get diagnostics v_count = row_count;
  return v_count;
end $$;


