--
-- Name: purge_old_location_data(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_location_data(p_days integer DEFAULT 180) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cutoff timestamptz := now() - make_interval(days => greatest(p_days, 30));
  v_tracking bigint := 0;
  v_fs bigint := 0;
  v_tech bigint := 0;
  v_pop bigint := 0;
begin
  delete from public.tracking_points where recorded_at < v_cutoff;
  get diagnostics v_tracking = row_count;

  delete from public.fs_gps_points where recorded_at < v_cutoff;
  get diagnostics v_fs = row_count;

  delete from public.technician_locations where recorded_at < v_cutoff;
  get diagnostics v_tech = row_count;

  -- proof_of_presence porte une valeur probatoire (preuve de passage sur un
  -- chantier): conservee plus longtemps que la trace de deplacement brute,
  -- alignee sur la prescription civile courante.
  delete from public.proof_of_presence
  where recorded_at < now() - interval '3 years';
  get diagnostics v_pop = row_count;

  return jsonb_build_object(
    'tracking_points', v_tracking,
    'fs_gps_points', v_fs,
    'technician_locations', v_tech,
    'proof_of_presence', v_pop,
    'cutoff', v_cutoff
  );
end $$;


--
-- Name: FUNCTION purge_old_location_data(p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_old_location_data(p_days integer) IS 'Purge les traces de geolocalisation au-dela de p_days (defaut 180). Loi 25 : un RP ne se conserve pas au-dela de sa finalite.';


--
-- Name: purge_old_soft_deletes(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_soft_deletes(p_org_id uuid, p_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_cutoff timestamptz := now() - (p_days || ' days')::interval;
  v_counts jsonb := '{}'::jsonb;
  tbl text;
  v_count int;
BEGIN
  IF NOT has_org_admin_role(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'Admin role required';
  END IF;

  FOR tbl IN SELECT unnest(ARRAY['clients','leads','jobs','invoices','pipeline_deals','schedule_events','notifications'])
  LOOP
    -- Archive before purge
    EXECUTE format(
      'INSERT INTO archived_records (org_id, entity_type, entity_id, entity_data, archived_by, reason)
       SELECT org_id, %L, id, to_jsonb(t.*), $2, ''auto_purge_'' || $3 || ''d''
       FROM %I t WHERE org_id = $1 AND deleted_at IS NOT NULL AND deleted_at < $4
       ON CONFLICT (org_id, entity_type, entity_id) DO NOTHING',
      rtrim(tbl, 's'), tbl
    ) USING p_org_id, auth.uid(), p_days, v_cutoff;

    EXECUTE format(
      'DELETE FROM %I WHERE org_id = $1 AND deleted_at IS NOT NULL AND deleted_at < $2',
      tbl
    ) USING p_org_id, v_cutoff;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object(tbl, v_count);
  END LOOP;

  -- Purge old audit events (keep 1 year)
  DELETE FROM audit_events WHERE org_id = p_org_id AND created_at < now() - INTERVAL '1 year';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('audit_events', v_count);

  RETURN v_counts;
END;
$_$;


