--
-- Name: set_invoice_client_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_client_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name  text;
  v_email text;
BEGIN
  IF NEW.client_id IS NOT NULL AND (NEW.client_name_snapshot IS NULL OR NEW.client_name_snapshot = '') THEN
    SELECT
      COALESCE(
        NULLIF(TRIM(CONCAT_WS(' ', c.first_name, c.last_name)), ''),
        NULLIF(c.company, ''),
        'Unknown client'
      ),
      c.email
    INTO v_name, v_email
    FROM public.clients c
    WHERE c.id = NEW.client_id;

    NEW.client_name_snapshot  := COALESCE(NEW.client_name_snapshot,  v_name);
    NEW.client_email_snapshot := COALESCE(NEW.client_email_snapshot, v_email);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_invoice_next_number(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_next_number(p_org uuid, p_next integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is not null and not public.has_org_admin_role(auth.uid(), p_org) then
    raise exception 'Only org owners or admins can change invoice numbering.' using errcode = '42501';
  end if;
  if p_next is null or p_next < 1 or p_next > 99999999 then
    raise exception 'Next invoice number must be between 1 and 99999999.';
  end if;

  insert into public.invoice_sequences (org_id, last_value, updated_at)
  values (p_org, p_next - 1, now())
  on conflict (org_id) do update
    set last_value = excluded.last_value,
        updated_at = now();
end;
$$;


