--
-- Name: trigger_sms_number_release(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_sms_number_release() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'net'
    AS $$
declare
  v_secret text;
  v_base   text;
begin
  select decrypted_secret into v_secret
    from vault.decrypted_secrets where name = 'cron_secret';

  if v_secret is null then
    raise exception 'Secret Vault "cron_secret" absent — liberation SMS non declenchee';
  end if;

  select coalesce(
    (select decrypted_secret from vault.decrypted_secrets where name = 'app_base_url'),
    'https://lumecrm.net'
  ) into v_base;

  perform net.http_post(
    url     := v_base || '/api/cron/release-sms-numbers',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', v_secret,
      'x-requested-with', 'XMLHttpRequest'
    ),
    body    := '{}'::jsonb
  );
end;
$$;


--
-- Name: try_advisory_lock(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.try_advisory_lock(p_key bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_claimed boolean;
begin
  insert into public.cron_locks (key, locked_until)
  values (p_key, now() + interval '10 minutes')
  on conflict (key) do update
    set locked_at = now(), locked_until = now() + interval '10 minutes'
    where cron_locks.locked_until < now()
  returning true into v_claimed;
  return coalesce(v_claimed, false);
end;
$$;


