--

CREATE TABLE public.pipeline_deals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.current_org_id() NOT NULL,
    lead_id uuid,
    stage_id uuid,
    value_cents integer DEFAULT 0 NOT NULL,
    currency text DEFAULT 'CAD'::text NOT NULL,
    probability integer DEFAULT 50 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    value numeric(12,2) DEFAULT 0 NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    job_id uuid,
    stage text NOT NULL,
    title text NOT NULL,
    notes text,
    client_id uuid,
    lost_at timestamp with time zone,
    deleted_by uuid,
    archived_at timestamp with time zone,
    archived_by uuid,
    won_at timestamp with time zone,
    rep_id uuid,
    d2d_status text DEFAULT 'pending'::text,
    lost_reason text,
    pin_id uuid,
    quote_id uuid,
    source text DEFAULT 'manual'::text,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT pipeline_deals_origin_check CHECK (((lead_id IS NOT NULL) OR (client_id IS NOT NULL))),
    CONSTRAINT pipeline_deals_probability_check CHECK (((probability >= 0) AND (probability <= 100))),
    CONSTRAINT pipeline_deals_stage_check CHECK ((stage = ANY (ARRAY['new_prospect'::text, 'no_response'::text, 'quote_sent'::text, 'closed_won'::text, 'closed_lost'::text])))
);

ALTER TABLE ONLY public.pipeline_deals FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE pipeline_deals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pipeline_deals IS '[CRM] Sales pipeline deals (lead to job progression)';


--
-- Name: COLUMN pipeline_deals.won_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pipeline_deals.won_at IS 'Timestamp when deal moved to closed_won. Used for auto-removal after 2 days.';


--
-- Name: pipeline_deals_active; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pipeline_deals_active WITH (security_invoker='true') AS
 SELECT id,
    org_id,
    lead_id,
    stage_id,
    value_cents,
    currency,
    probability,
    created_at,
    updated_at,
    deleted_at,
    value,
    created_by,
    job_id,
    stage,
    title,
    notes,
    client_id,
    lost_at,
    deleted_by
   FROM public.pipeline_deals
  WHERE (deleted_at IS NULL);


--
-- Name: pipeline_deals_visible; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pipeline_deals_visible WITH (security_invoker='true') AS
 SELECT id,
    org_id,
    lead_id,
    stage_id,
    value_cents,
    currency,
    probability,
    created_at,
    updated_at,
    deleted_at,
    value,
    created_by,
    job_id,
    stage,
    title,
    notes,
    client_id,
    lost_at,
    deleted_by,
    archived_at,
    archived_by,
    won_at,
    rep_id,
    d2d_status,
    lost_reason,
    pin_id,
    quote_id,
    source
   FROM public.pipeline_deals pd
  WHERE ((deleted_at IS NULL) AND ((lead_id IS NULL) OR (EXISTS ( SELECT 1
           FROM public.clients c
          WHERE ((c.id = pd.lead_id) AND (c.deleted_at IS NULL))))) AND ((client_id IS NULL) OR (EXISTS ( SELECT 1
           FROM public.clients c
          WHERE ((c.id = pd.client_id) AND (c.deleted_at IS NULL))))) AND (NOT ((stage = 'closed_won'::text) AND (won_at IS NOT NULL) AND (won_at < (now() - '2 days'::interval)))) AND (NOT ((stage = 'closed_lost'::text) AND (lost_at IS NOT NULL) AND (lost_at < (now() - '15 days'::interval)))));


--
-- Name: VIEW pipeline_deals_visible; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.pipeline_deals_visible IS 'Pipeline deals displayed in the Kanban. Filters out deleted, orphaned, and expired WON/LOST deals.';


