--
-- Name: v_revenue_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_revenue_analytics WITH (security_invoker='true') AS
 SELECT p.org_id,
    (date_trunc('month'::text, (p.payment_date AT TIME ZONE 'America/Toronto'::text)))::date AS month,
    p.currency,
    p.method,
    (count(*))::integer AS payment_count,
    sum(p.amount_cents) AS total_cents,
    (avg(p.amount_cents))::integer AS avg_cents,
    c.id AS client_id,
    ((c.first_name || ' '::text) || c.last_name) AS client_name,
    c.company AS client_company
   FROM (public.payments p
     LEFT JOIN public.clients c ON (((c.id = p.client_id) AND (c.deleted_at IS NULL))))
  WHERE ((p.deleted_at IS NULL) AND (p.status = 'succeeded'::text))
  GROUP BY p.org_id, ((date_trunc('month'::text, (p.payment_date AT TIME ZONE 'America/Toronto'::text)))::date), p.currency, p.method, c.id, c.first_name, c.last_name, c.company;


--
-- Name: v_schedule_calendar; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_schedule_calendar WITH (security_invoker='true') AS
 SELECT se.id AS event_id,
    se.org_id,
    se.start_at,
    se.end_at,
    se.status AS event_status,
    se.notes AS event_notes,
    se.timezone,
    j.id AS job_id,
    j.job_number,
    j.title AS job_title,
    j.status AS job_status,
    j.address AS job_address,
    c.id AS client_id,
    ((c.first_name || ' '::text) || c.last_name) AS client_name,
    c.phone AS client_phone,
    t.id AS team_id,
    t.name AS team_name,
    t.color_hex AS team_color
   FROM (((public.schedule_events se
     LEFT JOIN public.jobs j ON (((j.id = se.job_id) AND (j.deleted_at IS NULL))))
     LEFT JOIN public.clients c ON (((c.id = j.client_id) AND (c.deleted_at IS NULL))))
     LEFT JOIN public.teams t ON (((t.id = se.team_id) AND (t.deleted_at IS NULL))))
  WHERE (se.deleted_at IS NULL);


